/**
 * AXI-native default output formatter (https://axi.md).
 *
 * `@superdesign/cli` is invoked overwhelmingly by AI agents through the
 * SuperDesign skill, so the DEFAULT (non-`--json`) output is designed for them:
 * token-efficient TOON-style records, minimal field sets, content truncation
 * with an explicit size hint + a `--full` escape hatch, definitive empty
 * states, and `help[N]:` contextual disclosure of concrete next-step commands.
 *
 * `--json` output is the STABLE machine contract and is produced elsewhere; this
 * module only shapes the human/agent-readable default. Every builder here is a
 * PURE function returning a string, so each is unit-testable without a network
 * call, and every command routes its default output through this one util
 * instead of hand-rolling strings.
 */
/** Write a rendered block to stdout (the data channel). */
export declare function emit(block: string): void;
/** Write a single diagnostic/metadata line to stderr (never the data channel). */
export declare function emitDiag(line: string): void;
/**
 * Escape a single TOON cell. Rows are comma-separated, so a value containing a
 * comma, double-quote, or newline is wrapped in double-quotes with internal
 * quotes doubled - keeping every row unambiguous to parse.
 */
export declare function escapeCell(value: string): string;
/**
 * Truncate a single-line field to `max` characters, appending an explicit size
 * hint pointing at the `--full` escape hatch (AXI principle 3). Returns the
 * value unchanged when `full` is set or it already fits.
 */
export declare function truncateField(value: string, max: number, full?: boolean): string;
/** A field in a TOON record header. `max` truncates the cell unless `--full`. */
export interface FieldSpec {
    key: string;
    max?: number;
}
export interface ToonRecordsInput<T> {
    /** Collection name shown in the header, e.g. `prompts`. */
    name: string;
    items: T[];
    fields: FieldSpec[];
    /** Map an item to a flat record keyed by the field keys. */
    row: (item: T) => Record<string, string>;
    /** Definitive empty-state message (AXI principle 5), never blank output. */
    emptyState: string;
    /** Disable truncation (the `--full` escape hatch). */
    full?: boolean;
}
/**
 * Render a TOON-style record block:
 *
 *   prompts[2]{slug,title,tags}:
 *     hero-dark,"Bold dark hero",landing;dark
 *     pricing,"Pricing table",pricing
 *
 * When empty, renders a definitive one-line empty state instead of a bare
 * header: `prompts[0]: <emptyState>`.
 */
export declare function formatToonRecords<T>(input: ToonRecordsInput<T>): string;
/** A concrete next-step suggestion for a `help[N]:` block. */
export interface HelpItem {
    command: string;
    /** Verb phrase read after the backticked command, gh-axi style. */
    purpose: string;
}
/**
 * Render a `help[N]:` contextual-disclosure block (AXI principle 9), modelled
 * on gh-axi / chrome-devtools-axi:
 *
 *   help[2]:
 *     Run `superdesign get-design --draft-id drf_1` to fetch the generated HTML
 *     Run `superdesign iterate-design-draft ...` to explore variations
 */
export declare function formatHelp(items: HelpItem[]): string;
/** A labelled line in a mutation result block; empty values are dropped. */
export interface ResultField {
    label: string;
    value: string | number | null | undefined;
}
/**
 * Render a compact mutation result block: a `title:` line, aligned
 * `label  value` lines for the essential ids / URLs, then a `help[N]:` block.
 */
export declare function formatResultBlock(input: {
    title: string;
    fields: ResultField[];
    help: HelpItem[];
}): string;
export declare function previewUrlFor(draftId: string): string;
export declare function canvasUrlFor(teamId: string, projectId: string): string;
export declare const nextSteps: {
    iterate: (draftId: string) => HelpItem;
    iterateReplace: (draftId: string) => HelpItem;
    getDesign: (draftId: string) => HelpItem;
    fetchNodes: (projectId: string) => HelpItem;
    createDraft: (projectId: string) => HelpItem;
    listComponents: (projectId: string) => HelpItem;
    createComponent: (projectId: string) => HelpItem;
    updateComponent: (componentId: string) => HelpItem;
    createProjectExtend: (designSystemId: string) => HelpItem;
    getPromptsFull: (slug: string) => HelpItem;
    searchPromptsBroaden: () => HelpItem;
    revert: (draftId: string) => HelpItem;
    iterateFromVersion: (draftId: string) => HelpItem;
    importInto: (draftId: string) => HelpItem;
};
